add_action( 'woocommerce_product_query', 'perfectpixel_hide_products_by_country_query' );
add_filter( 'woocommerce_is_purchasable', 'perfectpixel_hide_products_by_country_purchasable', 60, 2 );

function perfectpixel_visitor_in_hidden_country() {
	static $hidden = null;
	if ( null === $hidden ) {
		$countries = array_filter( array_map( 'trim', explode( ',', strtoupper( '{{geo_hidden_countries}}' ) ) ) );
		$location  = class_exists( 'WC_Geolocation' ) ? WC_Geolocation::geolocate_ip( '', true, true ) : array();
		$hidden    = $countries && ! empty( $location['country'] ) && in_array( $location['country'], $countries, true );
	}
	return $hidden;
}

function perfectpixel_hide_products_by_country_query( $q ) {
	$ids = wp_parse_id_list( '{{geo_hidden_product_ids}}' );
	if ( $ids && perfectpixel_visitor_in_hidden_country() ) {
		$q->set( 'post__not_in', array_merge( (array) $q->get( 'post__not_in' ), $ids ) );
	}
}

function perfectpixel_hide_products_by_country_purchasable( $purchasable, $product ) {
	$id = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
	if ( $purchasable && ! is_admin() && in_array( $id, wp_parse_id_list( '{{geo_hidden_product_ids}}' ), true ) && perfectpixel_visitor_in_hidden_country() ) {
		return false;
	}
	return $purchasable;
}
